    let data: any = {};
    let raw = "";
    let lastError = "";
    for (const model of models) {
      let response;
      try { response = await fetch("https://generativelanguage.googleapis.com/v1beta/interactions", {
        method: "POST",
        headers: { "Content-Type": "application/json", "x-goog-api-key": key },
